// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    FuzzToken tok;

    function setUp() public { c = new PoCGame(address(this), 0); tok = new FuzzToken(); }

    function testFuzz_property(address tokenOwner, uint256 tokens, bool succeed) public {
        tok.setSucceed(succeed);
        bool ok = c.transferAnyERC20Token(address(tok), tokenOwner, tokens);
        assertTrue(ok == tok.lastTransferResult());
    }
}

contract FuzzToken {
    bool public succeed;
    bool public lastTransferResult;
    function setSucceed(bool s) external { succeed = s; }
    function transfer(address, uint256) external returns (bool) {
        lastTransferResult = succeed;
        return succeed;
    }
}
